264	        assertThat(conflict.status()).isEqualTo(409);
265	
266	        // 失败不占键：先以某 requestId 触发 422，再用同键修正参数后成功
267	        String failKey = newRequestId();
268	        ApiResult failed = postJson("/api/documents",
269	                "{\"requestId\":\"" + failKey + "\",\"targetLanguages\":[\"en\",\"en\"],\"segments\":[]}");
270	        assertThat(failed.status()).isEqualTo(422);
271	        ApiResult retried = postJson("/api/documents",
272	                "{\"requestId\":\"" + failKey + "\",\"targetLanguages\":[\"en\"],\"segments\":[]}");
273	        assertThat(retried.status()).isEqualTo(201);
274	    }
